                      )}>
                      <Icon className="h-4 w-4 shrink-0" aria-hidden="true" />
                      <span
                        className={cn(
                          'min-w-0 flex-1 truncate whitespace-nowrap transition-[max-width,opacity,transform] duration-150 ease-out motion-reduce:transition-none',
